Update Consent by ID > API /consents/{consentId}

 "tags": [
 "consents"
 ],
 "summary": "Patches one or more fields in a consent",
 "description": "This operation allows an financial institution modify fields within a consent's `consentBody`.\n\nTypically, this API would be called after the PSU has authorised a consent. This would\nallow the financial institution to \"patch in\" the `psuIdentifier` and `accountIds` associated with the\nconsent.\n\nThis is also called as authentication progresses for a multi-auth consent.\n",
 "operationId": "patchConsent",
 "parameters": [
 {
 "$ref": "#/components/parameters/consentId"
 }
 ],
 "requestBody": {
 "required": true,
 "content": {
 "application/json": {
 "schema": {
 "$ref": "#/components/schemas/ConsentManager.AEConsentUpdateProperties"
 }
 }
 }
 },
 "responses": {
 "204": {
 "description": "Indicates a successful operation.\nThe response does not have a body.\n"
 },
 "400": {
 "description": "Indicates a failure to patch the consent\n",
 "content": {
 "application/json": {
 "schema": {
 "$ref": "#/components/schemas/error400Response"
 }
 }
 }
 }
 }
 }
 },
 "security": [
 {},
 {
 "OzoneConnectJwtAuth": []
 }
 ],
 "securitySchemes": {
 "OzoneConnectJwtAuth": {
 "description": "Communications between the API Hub and the LFI Ozone Connect implementation are secured using the \"JWT Auth\" mechanism, where the Client presents a signed JSON Web Token as a credential.\n\nThe Server MUST verify the signature in order to authenticate the Client.\n\nPlease note that the value of the `scheme` parameter is not a registered HTTP Authentication Scheme, to indicate it is specific to Ozone Connect. Please refer to API Hub documentation for further details.\n",
 "type": "http",
 "scheme": "Ozone-Connect-JWT-Auth"
 }
 }
}

